    private static async Task<List<object>> GetEopReasonByEmploymentTypeId(
        AppDbContext db,
        string employmentTypeId,
        int agreementTypeId)
    {
        return await db.Set<EopReasonType>()
            .Where(e => e.EmploymentTypeId == employmentTypeId && e.AgreementTypeId == agreementTypeId)
            .Select(e => new { id = e.Id, name = e.Name } as object)
            .ToListAsync();
    }

    private static async Task<List<object>> GetEopReasonForExtension(AppDbContext db)
    {
        return await db.Set<EopReasonType>()
            .Where(e => e.ReasonType == "extension")
            .Select(e => new { id = e.Id, name = e.Name } as object)
            .ToListAsync();
    }

    private static async Task<List<object>> GetEopReasonForBenchPlacements(AppDbContext db)
    {
        return await db.Set<EopReasonType>()
            .Where(e => e.ReasonType == "bench")
            .Select(e => new { id = e.Id, name = e.Name } as object)
            .ToListAsync();
    }

    private static async Task<List<Dictionary<string, object>>> GetStatesList(
        AppDbContext db,
        bool param1,
        bool param2,
        bool selectOne,
        string[]? except = null)
    {
        var query = db.Set<States>().AsQueryable();
        if (except != null && except.Length > 0)
        {
            query = query.Where(s => !except.Contains(s.Description ?? ""));
        }
        var states = await query.ToListAsync();
        var result = new List<Dictionary<string, object>>();
        if (selectOne)
        {
            result.Add(new Dictionary<string, object> { { "id", "" }, { "value", "-- Select One --" } });
        }
        foreach (var state in states)
        {
            result.Add(new Dictionary<string, object>
            {
                { "id", state.Id },
                { "value", state.Description ?? "" }
            });
        }
        return result;
    }

    private static string TranslateState(string stateValue)
    {
        // Legacy States::translate mapping — stub for brevity; actual mapping
        // would come from States domain entity or config.
        return stateValue?.ToUpper() ?? "";
    }

    private static async Task<List<Dictionary<string, object>>> GetEopHistoryByPlacementId(
        AppDbContext db,
        int placementId)
    {
        return await db.Set<EopProcessed>()
            .Where(e => e.ContractorPlacementId == placementId.ToString())
            .OrderByDescending(e => e.CreatedAt)
            .Select(e => new Dictionary<string, object>
            {
                { "eop_status_type_id", e.EopStatusTypeId ?? 0 },
                { "eop_reason_type_id", e.EopReasonTypeId ?? 0 },
                { "update_on", e.UpdatedAt ?? DateTime.UtcNow },
                { "proposed_date", e.ProposedDate ?? DateTime.UtcNow },
                { "created_by", e.CreatedBy ?? "" }
            })
            .ToListAsync();
    }

    private static string ToDisplayDate(DateTime date)
    {
        return date.ToString("MM/dd/yyyy");
    }

    private static DateTime FromDisplayDate(string dateStr)
    {
        if (DateTime.TryParseExact(dateStr, "MM/dd/yyyy", System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out var result))
        {
            return result;
        }
        return new DateTime(2000, 1, 1);
    }

    private static async Task<DateTime> GetContractorPlacementStartDate(AppDbContext db, int placementId)
    {
        var placement = await db.Set<ContractorPlacement>().FindAsync(placementId.ToString());
        return placement?.StartDate ?? DateTime.MinValue;
    }

    private static async Task<DateTime> GetLastEnteredTsDate(AppDbContext db, int placementId)
    {
        var lastTs = await db.Set<Timesheet>()
            .Where(t => t.ContractorPlacementId == placementId.ToString())
            .OrderByDescending(t => t.TimesheetDate)
            .FirstOrDefaultAsync();
        return lastTs?.TimesheetDate ?? DateTime.MinValue;
    }

    private static async Task<int> GetEopWorkflowStatusId(AppDbContext db, string statusName)
    {
        var status = await db.Set<EopWorkflowStatusType>()
            .Where(s => s.Name == statusName)
            .FirstOrDefaultAsync();
        return status?.Id ?? 0;
    }

    private static async Task<int> GetEopStatusTypeId(AppDbContext db, string statusName)
    {
        var status = await db.Set<EopStatusType>()
            .Where(s => s.Name == statusName)
            .FirstOrDefaultAsync();
        return status?.Id ?? 0;
    }

    private static async Task<int> TranslateStateId(AppDbContext db, string? stateName)
    {
        if (string.IsNullOrEmpty(stateName)) return 0;
        var state = await db.Set<States>()
            .Where(s => s.Description == stateName)
            .FirstOrDefaultAsync();
        return state?.Id ?? 0;
    }

    private static async Task<decimal> CheckMinimumBenchPayRate(
        AppDbContext db,
        string zip,
        int stateId,
        DateTime effectiveDate,
        int payRateId)
    {
        var minWage = await db.Set<OnbMinimumPayStateMap>()
            .Where(m => m.Zip == zip && m.StateId == stateId && m.EffectiveDate <= effectiveDate)
            .OrderByDescending(m => m.EffectiveDate)
            .FirstOrDefaultAsync();
        return minWage?.MinimumRate ?? 0m;
    }

    private static async Task<int> GetCustomerClientPartnerId(AppDbContext db, int customerId)
    {
        var customer = await db.Set<Customer>().FindAsync(customerId.ToString());
        return customer?.ClientPartnerId ?? 1;
    }
